class Base { int b_data; };

// Left subobject contains a vbptr (Virtual Base Pointer)
class Left : virtual public Base {
    int l_data;
};

// Right subobject contains a vbptr
class Right : virtual public Base {
    int r_data;
};

// Diamond Problem resolved:
// Derived contains vbptr from Left, vbptr from Right,
// and ONE shared Base subobject (usually offset to the end)
class Derived : public Left, public Right {
    int d_data;
};

// Only one Base::b_data exists across the derived object.
